import { useMemo } from 'react';

import { PERFORMANCE_AND_BREAKDOWN_MOCK } from '../__mocks__/performanceAndBreakdownMocks';
import {
  PERFORMANCE_AND_BREAKDOWN_MOCK_FORCE_BY_SECTION,
  PERFORMANCE_AND_BREAKDOWN_MOCK_ONLY,
} from '../constants';
import type {
  PerformanceAndBreakdownMockForceFlags,
  PerformanceAndBreakdownOvertimeData,
  PerformanceAndBreakdownSectionDataResult,
  PerformanceAndBreakdownWaterfallData,
} from '../types';

export type PerformanceAndBreakdownSectionKey = 'overtime' | 'contribution';

type PerformanceAndBreakdownSectionDataMap = {
  overtime: PerformanceAndBreakdownOvertimeData;
  contribution: PerformanceAndBreakdownWaterfallData;
};

const noopRefetch = () => Promise.resolve();

function resolveMockView<T>(
  mockOnly: boolean,
  flags: PerformanceAndBreakdownMockForceFlags,
  getReadyData: () => T,
): PerformanceAndBreakdownSectionDataResult<T> {
  if (!mockOnly || flags.skeleton) {
    return { view: 'loading', data: null, refetch: noopRefetch };
  }

  if (flags.error) {
    return { view: 'error', data: null, refetch: noopRefetch };
  }

  if (flags.empty) {
    return { view: 'empty', data: null, refetch: noopRefetch };
  }

  return {
    view: 'ready',
    data: getReadyData(),
    refetch: noopRefetch,
  };
}

export function usePerformanceAndBreakdownSectionData<
  K extends PerformanceAndBreakdownSectionKey,
>(
  section: K,
): PerformanceAndBreakdownSectionDataResult<
  PerformanceAndBreakdownSectionDataMap[K]
> {
  return useMemo(
    (): PerformanceAndBreakdownSectionDataResult<
      PerformanceAndBreakdownSectionDataMap[K]
    > =>
      resolveMockView(
        PERFORMANCE_AND_BREAKDOWN_MOCK_ONLY,
        PERFORMANCE_AND_BREAKDOWN_MOCK_FORCE_BY_SECTION[section],
        () =>
          PERFORMANCE_AND_BREAKDOWN_MOCK[
            section
          ] as PerformanceAndBreakdownSectionDataMap[K],
      ),
    [section],
  );
}
